/**
 * System One decisions for Agent SDK host code.
 *
 * Chat models write. {@link evaluate} asks Jev for typed choice / score /
 * boolean answers over shared state. Call it from a project tool, a
 * router, or other host code after mounting `@grok/agent-sdk/extensions/jev`.
 * Do not set Jev as the `defineAgent` turn model.
 *
 * ```ts
 * import { evaluate, decide, above, needsHuman } from "@grok/agent-sdk/extensions/jev";
 *
 * const { answers } = await evaluate({
 *   state: draft,
 *   questions: {
 *     route: {
 *       type: "choice",
 *       instructions: "Which queue should handle this?",
 *       criteria: {
 *         billing: "charges, invoices, refunds",
 *         shipping: "delivery",
 *         technical: "bugs and outages",
 *       },
 *     },
 *     post: {
 *       type: "boolean",
 *       instructions: "Is this safe to post publicly?",
 *     },
 *   },
 * });
 *
 * if (needsHuman(answers.route) || !above(answers.post, 0.85)) {
 *   return { action: "review" };
 * }
 * ```
 *
 * Auth is `TYPESAFE_API_KEY`. `model` is a TypeSafe id (`jev-latest` by
 * default).
 */
import { isRecord } from "../../../internal/is-record.js";
/**
 * TypeSafe model used when {@link EvaluateArgs.model} is omitted.
 * @experimental
 */
export const DEFAULT_EVALUATION_MODEL = "jev-latest";
/**
 * Default bar for {@link needsHuman} when the caller does not pass one.
 * @experimental
 */
export const DEFAULT_HUMAN_THRESHOLD = 0.7;
const DEFAULT_BASE_URL = "https://api.typesafe.ai/v1";
/** Host behind the default base URL. */
export const DEFAULT_TYPESAFE_HOST = new URL(DEFAULT_BASE_URL).hostname;
/** Environment variable holding the TypeSafe key when a call passes no `apiKey`. */
export const TYPESAFE_API_KEY_ENV = "TYPESAFE_API_KEY";
function resolveApiKey(explicit) {
    const key = (explicit ?? process.env[TYPESAFE_API_KEY_ENV])?.trim();
    if (key === undefined || key === "") {
        throw new Error(`evaluate requires ${TYPESAFE_API_KEY_ENV}`);
    }
    return key;
}
function toWireQuestion(question) {
    if (question.type === "boolean") {
        return { type: "noul", instructions: question.instructions };
    }
    return question;
}
function numberRecord(value, label) {
    const record = asRecord(value, label);
    const numbers = {};
    for (const [key, item] of Object.entries(record)) {
        if (typeof item !== "number") {
            throw new Error(`evaluate ${label}`);
        }
        numbers[key] = item;
    }
    return numbers;
}
function asRecord(value, label) {
    if (!isRecord(value)) {
        throw new Error(`evaluate ${label}`);
    }
    return value;
}
function decodeAnswer(question, raw) {
    const value = asRecord(raw, "answer is missing");
    if (question.type === "boolean") {
        if (typeof value.noul !== "number") {
            throw new Error("evaluate noul is not a number");
        }
        return { type: "boolean", probability: value.noul };
    }
    if (question.type === "choice") {
        if (typeof value.choice !== "string") {
            throw new Error("evaluate choice is not a string");
        }
        return {
            type: "choice",
            choice: value.choice,
            probabilities: numberRecord(value.probabilities, "choice probabilities are missing"),
        };
    }
    if (typeof value.score !== "number") {
        throw new Error("evaluate score is not a number");
    }
    return {
        type: "score",
        score: value.score,
        probabilities: numberRecord(value.probabilities, "score probabilities are missing"),
    };
}
async function postSystemOne(args) {
    const response = await args.fetch(args.url, {
        method: "POST",
        headers: {
            Authorization: `Bearer ${args.apiKey}`,
            "Content-Type": "application/json",
        },
        body: JSON.stringify(args.body),
    });
    const text = await response.text();
    let parsed;
    try {
        parsed = text.length === 0 ? {} : JSON.parse(text);
    }
    catch {
        throw new Error(`evaluate returned non-JSON (${response.status})`);
    }
    if (!response.ok) {
        throw new Error(`evaluate failed (${response.status}): ${text.slice(0, 240)}`);
    }
    return asRecord(asRecord(parsed, "response is not an object").answers, "response is missing answers");
}
/**
 * Ask Jev for typed answers over one state.
 * @experimental
 */
export async function evaluate(args) {
    const questions = {};
    for (const [id, question] of Object.entries(args.questions)) {
        questions[id] = toWireQuestion(question);
    }
    const raw = await postSystemOne({
        url: `${(args.baseUrl ?? DEFAULT_BASE_URL).replace(/\/$/u, "")}/systemone`,
        apiKey: resolveApiKey(args.apiKey),
        fetch: args.fetch ?? globalThis.fetch,
        body: {
            model: args.model ?? DEFAULT_EVALUATION_MODEL,
            state: args.state,
            questions,
        },
    });
    const answers = {};
    for (const id of Object.keys(args.questions)) {
        const question = args.questions[id];
        if (question === undefined) {
            continue;
        }
        answers[id] = decodeAnswer(question, raw[id]);
    }
    return {
        // oxlint-disable-next-line typescript/no-unsafe-type-assertion -- Q is the caller's question map; each decoded answer matches that question and a record cannot express the map
        answers: answers,
    };
}
/**
 * Same as {@link evaluate}, returning only `answers`.
 * @experimental
 */
export async function decide(args) {
    const result = await evaluate(args);
    return result.answers;
}
/** @experimental */
export function above(answer, threshold) {
    if (answer.type === "boolean") {
        return answer.probability >= threshold;
    }
    return answer.score >= threshold;
}
/** @experimental */
export function needsHuman(answer, threshold = DEFAULT_HUMAN_THRESHOLD) {
    if (answer.type === "boolean") {
        return answer.probability < threshold;
    }
    return answer.probabilities[answer.choice] < threshold;
}
